compute:
const debt = Number(totalDebt) || 0;
const r = (Number(averageRatePct) || 0) / 100 / 12;
const pmt = Number(monthlyPayment) || 0;
let bal = debt, months = 0, interestPaid = 0;
const minPay = bal * r + 1;
if (pmt <= minPay) { return { interestRatio: 999, monthsToClear: 0, totalInterest: 0, totalPaid: 0 }; }
while (bal > 0 && months < 1200) { const i = bal * r; interestPaid += i; bal = bal + i - pmt; months++; }
const totalPaid = debt + interestPaid;
const interestRatio = debt > 0 ? (interestPaid / debt) * 100 : 0;
return { interestRatio, monthsToClear: months, totalInterest: interestPaid, totalPaid };

bandKeyBody:
if (r < 5) return 'tiny';
if (r < 12) return 'normal';
if (r < 25) return 'notable';
if (r < 45) return 'high';
if (r < 80) return 'major';
return 'executive';
